"""generates libsrc/th_topo.hum.imo: the packages topology, monoid, cmonoid (from the lists below; run it, then libsrc/build.sh th_topo)"""
import sys, json
def L(*xs): return '\\n'.join(x.replace('\\', '\\\\') for x in xs)
def theory(name, req, conf, default, sig, rules, axioms, theorems, doc):
    q = lambda lst: '[' + ', '.join('"%s"' % x for x in lst) + ']'
    v = 'th' + name
    out = [f'{v}sig in List(String) := lines("{sig}")', f'{v}rules in List(String) := lines("{rules}")', f'{v}axioms in List(String) := lines("{axioms}")',
           f'{v}theorems in List(String) := lines("{theorems}")', f'{v}doc in String := "{doc}"',
           f'{v} in Theory := mktheory("{name}", {q(req)}, {q(conf)}, {"true" if default else "false"}, {v}sig, {v}rules, [], {v}axioms, {v}theorems, {v}doc)']
    return '\n'.join(out)
parts = ['-- th_topo.hum.imo -- the packages topology, monoid and cmonoid (generated by libsrc/gen/th_topo.py; human notation; lib/th_topo.imo is its translation).']
TOPO_THEOREMS = json.load(open('libsrc/gen/topo_theorems.json', encoding='utf-8')) if len(sys.argv) > 1 and sys.argv[1] == 'json' else None
topo_rules = L('cl(false) ==> false', 'cl(true) ==> true', 'cl(or(x, y)) ==> or(cl(x), cl(y))', 'cl(cl(x)) ==> cl(x)', 'cl(not(cl(not(cl(not(cl(x))))))) ==> cl(not(cl(x)))',
               'interior(x) ==> not(cl(not(x)))', 'bd(x) ==> and(cl(x), cl(not(x)))', 'ext(x) ==> not(cl(x))',
               'open(x) ==> subset(x, not(cl(not(x))))', 'closed(x) ==> subset(cl(x), x)',
               'or(x, cl(x)) ==> cl(x)', 'and(x, cl(x)) ==> x', 'or(x, cl(not(x))) ==> true', 'or(not(x), cl(x)) ==> true',
               'or(x, not(cl(not(x)))) ==> x', 'and(x, not(cl(not(x)))) ==> not(cl(not(x)))',
               'subset(x, cl(x)) ==> true', 'subset(not(cl(not(x))), x) ==> true', 'subset(cl(and(x, y)), and(cl(x), cl(y))) ==> true',
               'subset(not(cl(not(x))), cl(x)) ==> true', 'subset(cl(not(cl(not(x)))), cl(x)) ==> true', 'subset(not(cl(not(x))), not(cl(not(cl(x))))) ==> true',
               'subset(or(not(cl(not(x))), not(cl(not(y)))), not(cl(not(or(x, y))))) ==> true', 'cl(and(cl(x), cl(y))) ==> and(cl(x), cl(y))',
               'or(x, and(cl(x), cl(not(x)))) ==> cl(x)', 'and(x, or(not(cl(x)), not(cl(not(x))))) ==> not(cl(not(x)))')
topo_axioms = L('a topological space is a set U with a closure operator cl on its subsets (Kuratowski, 1922):',
                'K1 cl(∅) = ∅', 'K2 A ⊆ cl(A)', 'K3 cl(A ∪ B) = cl(A) ∪ cl(B)', 'K4 cl(cl(A)) = cl(A)',
                'equivalently, by the open sets: ∅ and U are open; a union of open sets is open; an intersection of two open sets is open (the closed sets are the complements of the open sets)',
                'the interior is int(A) = (cl(Aᶜ))ᶜ, the boundary is bd(A) = cl(A) ∩ cl(Aᶜ), the exterior is ext(A) = (cl(A))ᶜ; A is open if A = int(A), closed if A = cl(A)',
                'consequences used by the simplifier: cl is monotone and cl(A ∩ B) ⊆ cl(A) ∩ cl(B); int(A ∩ B) = int(A) ∩ int(B); and the theorem of Kuratowski: the closure and the complement generate at most 14 different operations: k k = k, c c = 1 and k c k c k c k = k c k',
                'the simplifier rewrites int, bd and ext into cl and complements, so that every statement about them is a statement of the algebra of sets about closures')
parts.append(theory('topology', ['sets'], [], False, L('fn 0 cl cl', 'fn 0 int interior', 'fn 0 bd bd', 'fn 0 ext ext', 'fn 0 open open', 'fn 0 closed closed'), topo_rules, topo_axioms,
                    L(*(TOPO_THEOREMS or ['cl(cl(A)) = cl(A)'])), 'topological spaces by the Kuratowski closure axioms: closure, interior, boundary and exterior as operators on the algebra of sets, with the normal forms of the 14-set theorem; requires sets'))
# monoids
mon_sig = L('infixl 7 ⋆ mop A', 'infixl 7 mop mop A', 'const 0 ε munit', 'const 0 munit munit')
mon_rules = L('mop(x, munit) ==> x', 'mop(munit, x) ==> x')
mon_axioms = L('a monoid is a set with an associative operation ⋆ and a neutral element ε:', 'M1 (x ⋆ y) ⋆ z = x ⋆ (y ⋆ z)', 'M2 x ⋆ ε = x', 'M3 ε ⋆ x = x',
               'nothing else is assumed: the operation need not be commutative (the words are free monoid words), and there is no cancellation: x ⋆ y = x ⋆ z does not give y = z; the package group adds inverses')
mon_thms = L('(x ⋆ y) ⋆ z = x ⋆ (y ⋆ z)', 'x ⋆ ε = x', 'ε ⋆ x = x', 'ε ⋆ ε = ε', 'x ⋆ ε ⋆ y = x ⋆ y', 'x ⋆ y ⋆ z ⋆ w = (x ⋆ y) ⋆ (z ⋆ w)', '(x ⋆ y) ⋆ ε = x ⋆ y', 'x ⋆ (ε ⋆ y ⋆ ε) = x ⋆ y',
             'x ⋆ y = y ⋆ x <=> x ⋆ y = y ⋆ x', 'x ⋆ x ⋆ x = x ⋆ (x ⋆ x)')
parts.append(theory('monoid', ['core'], ['cmonoid'], False, mon_sig, mon_rules, mon_axioms, mon_thms, 'monoids: an associative operation with a neutral element, the words of the free monoid; no commutativity and no cancellation'))
cmon_sig = L('infixl 7 ⋆ mop AC', 'infixl 7 mop mop AC', 'const 0 ε munit', 'const 0 munit munit')
cmon_axioms = L('a commutative monoid is a monoid whose operation is commutative:', 'M1 (x ⋆ y) ⋆ z = x ⋆ (y ⋆ z)', 'M2 x ⋆ ε = x', 'M3 ε ⋆ x = x', 'M4 x ⋆ y = y ⋆ x',
                'the words are multisets: x ⋆ y ⋆ x = x ⋆ x ⋆ y, but still x ⋆ x ≠ x (that is a semilattice)')
cmon_thms = L('x ⋆ y = y ⋆ x', 'x ⋆ y ⋆ z = z ⋆ y ⋆ x', 'x ⋆ y ⋆ x = x ⋆ x ⋆ y', 'x ⋆ ε = x', '(x ⋆ y) ⋆ (z ⋆ w) = (x ⋆ z) ⋆ (y ⋆ w)', 'x ⋆ y ⋆ ε ⋆ z = z ⋆ x ⋆ y')
parts.append(theory('cmonoid', ['core'], ['monoid'], False, cmon_sig, mon_rules, cmon_axioms, cmon_thms, 'commutative monoids: the words are multisets; excludes monoid'))
open('libsrc/th_topo.hum.imo', 'w', encoding='utf-8').write('\n'.join(parts) + '\n')
print('ok')
